from collections import Counter
roles=Counter()
for o in lines:
    if o['type']=='request':
        for d in o['delta']:
            roles[(d.get('role'))]+=1
print('roles in deltas:', roles)
print()
# Show one full request delta that includes an assistant message with tool_calls
for o in lines:
    if o['type']=='request':
        for d in o['delta']:
